    [Fact]
    public void Aes256GcmDecryptsThePublishedNistEmptyPlaintextVector()
    {
        // NIST AES_GCM.pdf, GCM-AES256 Example #1 (20–21): not generated by this implementation.
        using var engine = new CryptoEngine(Convert.FromHexString("FEFFE9928665731C6D6A8F9467308308FEFFE9928665731C6D6A8F9467308308"));
        byte[] payload = Convert.FromHexString("CAFEBABEFACEDBADDECAF888FD2CAA16A5832E76AA132C1453EEDA7E");
        Assert.Empty(engine.DecryptBytes(payload));
        payload[^1] ^= 1; Assert.ThrowsAny<CryptographicException>(() => engine.DecryptBytes(payload));
    }
    private static async Task<PwEntry> DetailedEntry(TestVault vault)
    {
        var entry = await vault.Add();
        entry.CustomFields.Add(new PwCustomField { Key = "recovery", Value = "protected-value", IsProtected = true });
        entry.Attachments.Add(new PwAttachment { FileName = "fixture.bin", Data = Enumerable.Range(0, 8192).Select(i => (byte)i).ToArray() });
        entry.History.Add(entry.CreateHistorySnapshot());
        await vault.Storage.SaveEntryAsync(entry, vault.Crypto); return entry;
    }

    [Fact]
    public async Task OverviewOmitsHeavyCollectionsAndFullDetailsLoadSeparately()
    {
        using var vault = await TestVault.Create(); var original = await DetailedEntry(vault);
        var overview = Assert.Single((await vault.Storage.LoadSnapshotAsync(vault.Crypto, includeDetails: false)).Entries);
        Assert.False(overview.HasLoadedDetails); Assert.Empty(overview.Attachments); Assert.Empty(overview.History); Assert.Empty(overview.CustomFields);
        Assert.Equal(original.Password, overview.Password); Assert.Equal(original.Notes, overview.Notes); Assert.Equal(original.Revision, overview.Revision);
        var selected = await vault.Storage.LoadEntryOverviewAsync(original.Id, vault.Crypto, original.Revision);
        Assert.False(selected.HasLoadedDetails);
        Assert.Equal(original.Password, selected.Password);
        Assert.Empty(selected.Attachments);
        await Assert.ThrowsAsync<VaultConflictException>(() => vault.Storage.LoadEntryOverviewAsync(original.Id, vault.Crypto, original.Revision - 1));
        selected.ClearSecrets();
        var full = await vault.Storage.LoadEntryAsync(overview.Id, vault.Crypto, overview.Revision);
        Assert.True(full.HasLoadedDetails); Assert.Single(full.CustomFields); Assert.Single(full.History);
        Assert.Equal(original.Attachments[0].Data, Assert.Single(full.Attachments).Data);
    }

    [Fact]
    public async Task CredentialReadsSelectOneFieldAndRejectStaleRevisions()
    {
        using var vault = await TestVault.Create();
        var entry = await DetailedEntry(vault);
        entry.UserName = "Account 🚀";
        entry.Password = "Synthetic!\"\\🏔";
        entry.Notes = "Fixture note";
        await vault.Storage.SaveEntryAsync(entry, vault.Crypto);
        long revision = entry.Revision;

        Assert.Equal(entry.UserName, await vault.Storage.LoadEntryUserNameAsync(entry.Id, vault.Crypto, revision));
        Assert.Equal(entry.Password, await vault.Storage.LoadEntryPasswordAsync(entry.Id, vault.Crypto, revision));
        var json = EntrySerialization.Serialize(entry);
        var userNameOnly = JsonSerializer.Deserialize<PwEntry>(json, EntrySerialization.UserNameOptions)!;
        var passwordOnly = JsonSerializer.Deserialize<PwEntry>(json, EntrySerialization.PasswordOptions)!;
        Assert.Equal(entry.UserName, userNameOnly.UserName);
        Assert.Empty(userNameOnly.Password);
        Assert.Equal(entry.Password, passwordOnly.Password);
        Assert.Empty(passwordOnly.UserName);
        Assert.Empty(userNameOnly.Notes);
        Assert.Empty(passwordOnly.Notes);
        Assert.Empty(passwordOnly.Attachments);

        entry.Password = string.Empty;
        await vault.Storage.SaveEntryAsync(entry, vault.Crypto);
        await Assert.ThrowsAsync<VaultConflictException>(() => vault.Storage.LoadEntryUserNameAsync(entry.Id, vault.Crypto, revision));
        await Assert.ThrowsAsync<VaultConflictException>(() => vault.Storage.LoadEntryPasswordAsync(entry.Id, vault.Crypto, revision));
        Assert.Empty(await vault.Storage.LoadEntryPasswordAsync(entry.Id, vault.Crypto, entry.Revision));
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            vault.Storage.LoadEntryPasswordAsync(entry.Id, vault.Crypto, entry.Revision, new CancellationToken(canceled: true)));
        Assert.False(vault.Storage.IsReadOnly);
    }

    [Fact]
    public async Task PartialModelsCannotSilentlyOverwriteStoredDetails()
    {
        using var vault = await TestVault.Create(); var original = await DetailedEntry(vault);
        var overview = Assert.Single((await vault.Storage.LoadSnapshotAsync(vault.Crypto, false)).Entries);
        overview.Title = "partial edit";
        await Assert.ThrowsAsync<InvalidOperationException>(() => vault.Storage.SaveEntryAsync(overview, vault.Crypto));
        Assert.Throws<InvalidOperationException>(() => overview.DeepClone());
        Assert.Throws<InvalidOperationException>(() => overview.CreateHistorySnapshot());
        var reloaded = await vault.Storage.LoadEntryAsync(original.Id, vault.Crypto);
        Assert.Equal(original.Title, reloaded.Title); Assert.Single(reloaded.Attachments); Assert.Single(reloaded.History); Assert.False(vault.Storage.IsReadOnly);
    }

    [Fact]
    public async Task MovingAnOverviewPreservesUnloadedCollections()
    {
        using var vault = await TestVault.Create(); var original = await DetailedEntry(vault);
        var overview = Assert.Single((await vault.Storage.LoadSnapshotAsync(vault.Crypto, false)).Entries);
        long revision = await vault.Storage.MoveEntryAsync(overview.Id, overview.Revision, vault.Trash.Id, vault.Crypto);
        var full = await vault.Storage.LoadEntryAsync(overview.Id, vault.Crypto);
        Assert.Equal(vault.Trash.Id, full.GroupId); Assert.Equal(revision, full.Revision);
        Assert.Equal(original.Attachments[0].Data, Assert.Single(full.Attachments).Data);
        Assert.Single(full.History); Assert.Equal("protected-value", Assert.Single(full.CustomFields).Value);
    }

    [Fact]
    public async Task StreamingFolderTrashPreservesChildrenAndLeavesOtherEntriesUntouched()
    {
        using var vault = await TestVault.Create();
        var group = new PwGroup { Name = "folder", ParentId = vault.Root.Id }; await vault.Storage.SaveGroupAsync(group, vault.Crypto);
        var moved = await DetailedEntry(vault); var untouched = await DetailedEntry(vault);
        await vault.Storage.MoveEntryAsync(moved.Id, moved.Revision, group.Id, vault.Crypto);
        await vault.Storage.TrashGroupAsync(group.Id, vault.Crypto);
        var full = await vault.Storage.LoadEntryAsync(moved.Id, vault.Crypto);
        Assert.Equal(vault.Trash.Id, full.GroupId); Assert.Single(full.Attachments); Assert.Single(full.History); Assert.Single(full.CustomFields);
        var other = await vault.Storage.LoadEntryAsync(untouched.Id, vault.Crypto);
        Assert.Equal(vault.Root.Id, other.GroupId); Assert.Equal(untouched.Revision, other.Revision); Assert.Single(other.Attachments);
    }

    [Fact]
    public async Task StaleOverviewCannotMoveOrOpenAnOutdatedRevision()
    {
        using var vault = await TestVault.Create(); var original = await DetailedEntry(vault);
        var overview = Assert.Single((await vault.Storage.LoadSnapshotAsync(vault.Crypto, false)).Entries);
        original.Password = "new value"; await vault.Storage.SaveEntryAsync(original, vault.Crypto);
        await Assert.ThrowsAsync<VaultConflictException>(() => vault.Storage.MoveEntryAsync(overview.Id, overview.Revision, vault.Trash.Id, vault.Crypto));
        await Assert.ThrowsAsync<VaultConflictException>(() => vault.Storage.LoadEntryAsync(overview.Id, vault.Crypto, overview.Revision));
        var full = await vault.Storage.LoadEntryAsync(original.Id, vault.Crypto);
        Assert.Equal("new value", full.Password); Assert.Equal(vault.Root.Id, full.GroupId); Assert.Single(full.Attachments);
    }

    [Fact]
    public async Task StoredDraftDoesNotWriteHistoryOrOverwriteAConcurrentEdit()
    {
        using var vault = await TestVault.Create();
        var original = await vault.Add();
        long revision = original.Revision;
        var editable = await vault.Storage.LoadEntryAsync(original.Id, vault.Crypto, revision);
        using var draft = EntryEditDraft.TakeStoredEntry(editable,
            token => vault.Storage.LoadEntryAsync(original.Id, vault.Crypto, revision, token));
        draft.Current.Password = "stale draft value";
        original.Password = "concurrent edit";
        await vault.Storage.SaveEntryAsync(original, vault.Crypto);

        await Assert.ThrowsAsync<VaultConflictException>(() => draft.PrepareForSaveAsync());
        Assert.Empty(draft.Current.History);
        var saved = await vault.Storage.LoadEntryAsync(original.Id, vault.Crypto);
        Assert.Equal("concurrent edit", saved.Password);
        Assert.Empty(saved.History);
    }

    [Fact]
    public async Task StreamedKeyRotationPreservesEveryEntryAndItsChildren()
    {
        using var vault = await TestVault.Create(); var first = await DetailedEntry(vault); var second = await DetailedEntry(vault);
        using var replacement = new CryptoEngine(RandomNumberGenerator.GetBytes(32));
        await vault.Storage.ChangeMasterKeyAsync(vault.Crypto, replacement, Convert.ToBase64String(RandomNumberGenerator.GetBytes(16)), 1, 8192, 1, true);
        foreach (var id in new[] { first.Id, second.Id })
        {
            var full = await vault.Storage.LoadEntryAsync(id, replacement);
            Assert.Single(full.Attachments); Assert.Single(full.History); Assert.Single(full.CustomFields); Assert.Equal("secret", full.Password);
        }
    }

    private sealed class ReadProgress(Action<VaultReadProgress> report) : IProgress<VaultReadProgress>
    { public void Report(VaultReadProgress value) => report(value); }

    [Theory]
    [InlineData(VaultReadPhase.Verifying)]
    [InlineData(VaultReadPhase.LoadingEntries)]
    public async Task LoadingCanBeCancelledWithoutMakingTheVaultReadOnly(VaultReadPhase phase)
    {
        using var vault = await TestVault.Create(); await DetailedEntry(vault); using var cancellation = new CancellationTokenSource();
        var progress = new ReadProgress(value => { if (value.Phase == phase && value.Completed == value.Total) cancellation.Cancel(); });
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => vault.Storage.LoadSnapshotAsync(vault.Crypto, false, cancellation.Token, progress));
        Assert.False(vault.Storage.IsReadOnly);
        Assert.Single((await vault.Storage.LoadSnapshotAsync(vault.Crypto, false)).Entries);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task LoadingOneEntryStillAuthenticatesTheOtherRecords(bool passwordOnly)
    {
        using var vault = await TestVault.Create(); var valid = await DetailedEntry(vault); var damaged = await DetailedEntry(vault);
        vault.Sql($"UPDATE sp_entries SET payload=zeroblob(length(payload)) WHERE id='{damaged.Id}'");
        await Assert.ThrowsAsync<InvalidDataException>(() => passwordOnly
            ? vault.Storage.LoadEntryPasswordAsync(valid.Id, vault.Crypto, valid.Revision)
            : (Task)vault.Storage.LoadEntryAsync(valid.Id, vault.Crypto));
    }

    // Reference of the original format-2 canonicalization, kept separate from the streaming implementation.
    private static string OriginalManifest(SqliteConnection connection)
    {
        using var command = connection.CreateCommand(); command.CommandText = "SELECT metadata FROM sp_metadata WHERE singleton=1";
        var metadata = JsonSerializer.Deserialize<VaultMetadata>((string)command.ExecuteScalar()!)!;
        var builder = new StringBuilder(JsonSerializer.Serialize(metadata));
        command.CommandText = "SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name";
        using (var reader = command.ExecuteReader())
            while (reader.Read()) builder.Append('\n').Append(JsonSerializer.Serialize(new object[]
            { reader.GetString(0), reader.GetString(1), reader.GetString(2), reader.IsDBNull(3) ? "" : reader.GetString(3) }));
        foreach (string table in new[] { "sp_groups", "sp_entries" })
        {
            command.CommandText = $"SELECT * FROM {table} ORDER BY id COLLATE BINARY";
            using var reader = command.ExecuteReader();
            while (reader.Read()) builder.Append('\n').Append(JsonSerializer.Serialize(new object[]
            { table, reader.GetString(0), reader.IsDBNull(1) ? "" : reader.GetString(1), reader.GetInt64(2), Convert.ToHexString(SHA256.HashData((byte[])reader[3])) }));
        }
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(builder.ToString())));
    }

    [Fact]
    public async Task StreamedManifestMatchesTheOriginalFormat2Canonicalization()
    {
        using var vault = await TestVault.Create(); await DetailedEntry(vault);
        using var connection = new SqliteConnection(new SqliteConnectionStringBuilder { DataSource = vault.Storage.FilePath, Pooling = false }.ToString()); connection.Open();
        string context = "SQLitePass/manifest/" + OriginalManifest(connection);
        using var command = connection.CreateCommand(); command.CommandText = "SELECT authentication FROM sp_metadata WHERE singleton=1";
        Assert.Equal("SQLitePass manifest v2", vault.Crypto.DecryptString((string)command.ExecuteScalar()!, context));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(4096)]
    public void OptimizedAesGcmPreservesTheNonceTagCiphertextLayout(int size)
    {
        byte[] key = RandomNumberGenerator.GetBytes(32), plain = RandomNumberGenerator.GetBytes(size);
        using var engine = new CryptoEngine(key); using var independent = new AesGcm(key, 16);
        byte[] oldPayload = new byte[28 + size]; RandomNumberGenerator.Fill(oldPayload.AsSpan(0, 12));
        independent.Encrypt(oldPayload.AsSpan(0, 12), plain, oldPayload.AsSpan(28), oldPayload.AsSpan(12, 16), "compat"u8);
        Assert.Equal(plain, engine.DecryptBytes(oldPayload, "compat"));
        byte[] optimized = engine.EncryptBytes(plain, "compat"), decoded = new byte[size];
        independent.Decrypt(optimized.AsSpan(0, 12), optimized.AsSpan(28), optimized.AsSpan(12, 16), decoded, "compat"u8);
        Assert.Equal(plain, decoded);
    }

    [Fact]
    public async Task SnapshotAndDraftKeepFullChildrenWithoutRecursivelyCopyingHistory()
    {
        using var vault = await TestVault.Create(); var source = await DetailedEntry(vault);
        source.History[0].SnapshotJson = "older-history-marker";
        using var draft = EntryEditDraft.Create(source);
        Assert.DoesNotContain("older-history-marker", draft.Original.SnapshotJson);
        var snapshot = EntrySerialization.Deserialize(draft.Original.SnapshotJson);
        Assert.Single(snapshot.Attachments); Assert.Single(snapshot.CustomFields); Assert.Empty(snapshot.History);
        draft.Current.Attachments[0].Data[0] = 255; draft.Current.CustomFields[0].Value = "changed";
        Assert.Equal(0, source.Attachments[0].Data[0]); Assert.Equal("protected-value", source.CustomFields[0].Value);
    }

    [Fact]
    public async Task StorageSerializationDoesNotClearBorrowedSourceBuffers()
    {
        using var vault = await TestVault.Create(); var entry = await DetailedEntry(vault);
        var original = entry.Attachments[0].Data.ToArray(); string history = entry.History[0].SnapshotJson;
        await vault.Storage.SaveEntryAsync(entry, vault.Crypto);
        Assert.Equal(original, entry.Attachments[0].Data); Assert.Equal(history, entry.History[0].SnapshotJson);
        Assert.Equal(original, (await vault.Storage.LoadEntryAsync(entry.Id, vault.Crypto)).Attachments[0].Data);
    }

    [Fact]
    public void ClearingAnEntryDropsLiteralAutoTypeAndHistoricalTitles()
    {
        var entry = new PwEntry { Title = "private", AutoTypeSequence = "literal-secret" };
        var history = new PwEntryHistory { Title = "private old title", SnapshotJson = "private snapshot" };
        entry.History.Add(history); entry.ClearSecrets();
        Assert.Empty(entry.AutoTypeSequence); Assert.Empty(history.Title); Assert.Empty(history.SnapshotJson);
    }

    [Fact]
    public async Task CompleteValidationDoesNotTreatSkippedDetailsAsValidated()
    {
        using var vault = await TestVault.Create(); var entry = await DetailedEntry(vault);
        var node = JsonNode.Parse(EntrySerialization.Serialize(entry))!.AsObject();
        node[nameof(PwEntry.Attachments)]![0]![nameof(PwAttachment.Data)] = "invalid-base64!";
        string context = $"SQLitePass/v2/{(await vault.Storage.LoadVaultMetadataAsync())!.VaultId:D}/entries/{entry.Id:D}/{entry.GroupId:D}/{entry.Revision}";
        using var connection = new SqliteConnection(new SqliteConnectionStringBuilder { DataSource = vault.Storage.FilePath, Pooling = false }.ToString()); connection.Open();
        using var command = connection.CreateCommand(); command.CommandText = "UPDATE sp_entries SET payload=$payload WHERE id=$id";
        command.Parameters.AddWithValue("$id", entry.Id.ToString()); command.Parameters.AddWithValue("$payload", vault.Crypto.EncryptBytes(Encoding.UTF8.GetBytes(node.ToJsonString()), context)); command.ExecuteNonQuery();
        string authentication = vault.Crypto.EncryptString("SQLitePass manifest v2", "SQLitePass/manifest/" + OriginalManifest(connection));
        command.Parameters.Clear(); command.CommandText = "UPDATE sp_metadata SET authentication=$auth"; command.Parameters.AddWithValue("$auth", authentication); command.ExecuteNonQuery();
        Assert.False(Assert.Single((await vault.Storage.LoadSnapshotAsync(vault.Crypto, false)).Entries).HasLoadedDetails);
        await Assert.ThrowsAsync<InvalidDataException>(() => vault.Storage.ValidateContentsAsync(vault.Crypto));
    }
